use forge_core::{Document, SolidKind};
use std::io::ErrorKind;

/// Reproduction of the recorded object-ID exhaustion finding, re-run against the
/// current fallible authoring APIs. The project with an exhausted ID space still
/// loads; authoring now returns an authoring error instead of panicking, and the
/// document, its saved bytes and the ID allocator are unchanged.
fn main() {
    let mut document = Document::load_json("target/audit-id-limit.forge.json").unwrap();
    document.validate().unwrap();
    let before = document.clone();
    let before_json = document.to_json().unwrap();
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        document.add_solid("Box", SolidKind::Box)
    }));
    let error = match outcome {
        Ok(result) => match result {
            Ok(_) => panic!("authoring at the object ID limit must fail"),
            Err(error) => error,
        },
        Err(_) => panic!("authoring must not panic at the object ID limit"),
    };
    assert_eq!(error.kind(), ErrorKind::InvalidData);
    assert_eq!(error.to_string(), "Object ID space exhausted");
    assert_eq!(
        document, before,
        "a refused authoring call must not mutate the document"
    );
    assert_eq!(document.to_json().unwrap(), before_json);
    println!("Refused authoring at the object ID limit instead of panicking; document preserved");
}
